{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Anagliptin was reported to have oral bioavailability >73% in patients with T2DM, supporting F >=20%."
    },
    {
      "card_ids": ["C05"],
      "claim": "Fenspiride absolute oral bioavailability was 90% in healthy volunteers after an 80 mg slow-release tablet, supporting high bioavailability."
    },
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine mean absolute oral bioavailability was 18% in healthy subjects, providing affirmative evidence for F <20%."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C02"],
  "decision_summary": "Most transferred evidence molecules show high oral bioavailability (73–100%) in direct human studies, supporting high; one molecule (pentazocine) directly shows low bioavailability (~18%), so confidence is moderate.",
  "evidence_gaps": [
    "The evidence set is mixed: one direct low-bioavailability molecule conflicts with the predominantly high values, and assay-transfer scores do not clearly separate their applicability."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C31", "C05"],
  "revision_action": "initial",
  "supportive_card_ids": ["C31", "C05"]
}

